/** Command reference generated from the same Router definitions that run the CLI. */
import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";

import { app } from "../src/app.ts";
import { flattenRoutes } from "../src/kit/index.ts";

const destination = resolve(import.meta.dir, "../docs/reference.md");
const sections: string[] = [
  "# Command reference",
  "Generated by `bun run docs:generate` from the CLI's actual `--help` output. Edit command definitions to change options or descriptions; `bun run docs:check` verifies this file is current.",
  "[Documentation home](../README.md) · [Getting started](getting-started.md)",
  "Global options such as `--cwd` and `--verbose` go before the command: `sv --cwd ./project ready .`. A command's own options follow its name. Interactive examples and safety limits live in the workflow guides.",
];
for (const route of flattenRoutes(app.meta)) {
  let stdout = "";
  let stderr = "";
  const code = await app.run([...route.segments, "--help"], {
    cwd: "/",
    env: { NO_COLOR: "1" },
    stdout: {
      write: (chunk) => {
        stdout += chunk;
      },
    },
    stderr: {
      write: (chunk) => {
        stderr += chunk;
      },
    },
  });
  if (code !== 0 || stderr) throw new Error(`Cannot document ${route.path}: ${stderr}`);
  sections.push(
    `## ${[app.meta.name, ...route.segments].join(" ")}`,
    `\`\`\`text\n${stdout.trimEnd().replace(/[ \t]+$/gm, "")}\n\`\`\``,
  );
}
// Completion is a kit endpoint rather than a Router route.
sections.push(
  "## sv complete",
  "```text\nsv complete <zsh|bash|fish|powershell>\nsv complete -- <words...>\n```\n\nPrint shell integration or answer a completion request. See [shell setup](getting-started.md#shell-completion).",
);
const content = `${sections.join("\n\n")}\n`;
if (process.argv.includes("--check")) {
  const current = await readFile(destination, "utf8").catch(() => "");
  if (current !== content) {
    process.stderr.write("Command reference is out of date. Run bun run docs:generate.\n");
    process.exitCode = 1;
  }
} else {
  await writeFile(destination, content);
  process.stdout.write("Generated docs/reference.md\n");
}
